lib.common:
// Shared helpers for the clinic queue.
function clinic() { return db.query('SELECT * FROM clinic ORDER BY id LIMIT 1')[0] || {name: 'Clinic', tagline: ''}; }
function today() { return new Date(Date.now() + 4 * 3600 * 1000).toISOString().slice(0, 10); } // UAE date
function label(svc, n) { return (svc.prefix || '') + String(n).padStart(3, '0'); }
// Per active service: the number being served now and how many are waiting, for today.
function boards() {
  const d = today();
  return db.query('SELECT * FROM services WHERE active = 1 ORDER BY position, id').map(s => {
    const called = db.query("SELECT number FROM tickets WHERE service_id = ? AND day = ? AND status = 'called' ORDER BY called_at DESC, number DESC LIMIT 1", s.id, d)[0];
    const w = db.query("SELECT COUNT(*) AS n FROM tickets WHERE service_id = ? AND day = ? AND status = 'waiting'", s.id, d)[0].n;
    return {id: s.id, name: s.name, serving: called ? label(s, called.number) : '', waiting: w};
  });
}
function changed() { realtime.publish({channel: 'public:queue', data: {at: Date.now()}}); }

