scripts.home:
// GET /  the queue boards and the form to take a number.
function handle(req) {
  const errors = {full: 'Please choose a service and enter your name.', closed: 'This service is not taking numbers right now.'};
  return {template: 'home', data: {title: clinic().name, clinic: clinic(), services: boards(), error: errors[req.query.error] || ''}};
}

scripts.take:
// POST /take  form: service, name, phone. Gives the next number of the day for the service.
function handle(req) {
  const name = (req.form.name || '').trim().slice(0, 80), phone = (req.form.phone || '').trim().slice(0, 20);
  const svc = db.query('SELECT * FROM services WHERE id = ?', Number(req.form.service))[0];
  if (!svc || !name) return {redirect: '/?error=full'};
  if (!svc.active) return {redirect: '/?error=closed'};
  const d = today();
  const n = db.query('SELECT COALESCE(MAX(number), 0) + 1 AS n FROM tickets WHERE service_id = ? AND day = ?', svc.id, d)[0].n;
  const code = crypto.randomId();
  db.exec("INSERT INTO tickets (code, day, service_id, number, name, phone, status) VALUES (?, ?, ?, ?, ?, ?, 'waiting')", code, d, svc.id, n, name, phone);
  changed();
  return {redirect: '/t/' + code};
}

scripts.ticket:
// GET /t/:code  a visitor's own ticket, found by its secret code.
function handle(req) {
  const t = db.query('SELECT * FROM tickets WHERE code = ?', String(req.params.code))[0];
  if (!t) return {status: 404, text: 'Ticket not found'};
  const svc = db.query('SELECT * FROM services WHERE id = ?', t.service_id)[0] || {name: '', prefix: ''};
  const ahead = db.query("SELECT COUNT(*) AS n FROM tickets WHERE service_id = ? AND day = ? AND status = 'waiting' AND number < ?", t.service_id, t.day, t.number)[0].n;
  const b = boards().find(x => x.id === t.service_id);
  return {template: 'ticket', data: {title: label(svc, t.number), clinic: clinic(), ahead: ahead, serving: b ? b.serving : '',
    t: {label: label(svc, t.number), name: t.name, service: svc.name, status: t.status}}};
}

scripts.admin_change:
// on_admin_change: the reception calls a number in the admin panel (status called); stamp the time and update every screen.
function handle(req) {
  const b = req.body;
  if (b.table === 'tickets' && b.row && b.row.status === 'called' && (!b.before || b.before.status !== 'called')) {
    db.exec("UPDATE tickets SET called_at = datetime('now') WHERE id = ?", b.id);
  }
  if (b.table === 'tickets' || b.table === 'services') changed();
  return {text: 'ok'};
}
